import type {RateBook} from '@/lib/rates';
import {RevenueApprovalRecoveryPanel} from './revenue-approval-recovery-panel';
import {downloadReport} from '@/lib/report-export';

// Coordinated audit, authorization/concurrency and browser qualification are still pending.
const auditedSaveEnabled=false;
const amount=(value:string)=>{if(!/^\d{1,8}(\.\d{1,2})?$/.test(value.trim()))throw Error('Enter a valid USD amount.');return Math.round(Number(value)*100)};
export function RevenueRecommendationPreview({book,workspace,busy,actor,tenant,property,onApply,shadowMode=false}:{book:RateBook;workspace:HotelWorkspace;busy:boolean;actor:string;tenant:string;property:string;onApply:(approval:RevenueApproval)=>Promise<string|null>;shadowMode?:boolean}){
 const scope={actorId:actor,tenantId:tenant,propertyId:property},options=book.nightly_rates.map(rate=>{const plan=book.plans.find(item=>item.id===rate.plan_id);return plan?{...rate,plan}:null}).filter((value):value is NonNullable<typeof value>=>!!value),[selected,setSelected]=useState(''),[minimum,setMinimum]=useState(''),[maximum,setMaximum]=useState(''),[competitor,setCompetitor]=useState(''),[event,setEvent]=useState('0'),[reviewedKey,setReviewedKey]=useState<string|null>(null),[applying,setApplying]=useState(false),[actionError,setActionError]=useState(''),[receipt,setReceipt]=useState<RevenueDecisionReceipt|null>(null),[history,setHistory]=useState<RevenueDecisionReceipt[]>([]),[historyReady,setHistoryReady]=useState(false);
 useEffect(()=>{try{setHistory(readRevenueDecisionHistory(localStorage,scope));setActionError('')}catch(reason){setActionError(reason instanceof Error?reason.message:'Saved rate-decision history could not load.')}finally{setHistoryReady(true)}},[actor,tenant,property]);
 const row=options.find(item=>item.plan_id+'|'+item.stay_date===selected)??options[0]??null,capacity=row?workspace.capacity.find(item=>item.room_type_id===row.plan.room_type_id&&item.stay_date===row.stay_date):null;
 let result:ReturnType<typeof revenueRecommendation>|null=null,input:RevenueRecommendationInput|null=null,inputError='';if(row&&capacity&&capacity.effective_units!=null)try{input={stayDate:row.stay_date,currentRateMinor:row.amount_minor,effectiveUnits:capacity.effective_units,reservedUnits:capacity.reserved_units,minimumRateMinor:minimum?amount(minimum):Math.max(1,Math.round(row.amount_minor*.7)),maximumRateMinor:maximum?amount(maximum):Math.round(row.amount_minor*1.5),competitorRateMinor:competitor?amount(competitor):null,eventUpliftBasisPoints:Math.round(Number(event||0)*100)};result=revenueRecommendation(input)}catch(reason){inputError=reason instanceof Error?reason.message:'Review the recommendation inputs.'}
 const reviewKey=row&&input&&result?revenueReviewKey({...scope,currency:workspace.property.currency,planId:row.plan.id,planVersion:row.plan.version,planName:row.plan.name},input,result):null;
 const reviewed=reviewKey!==null&&reviewedKey===reviewKey;
 useEffect(()=>{setReviewedKey(null)},[reviewKey]);
 const edited=()=>{setReviewedKey(null);setActionError('');setReceipt(null)};
 async function apply(){if(!auditedSaveEnabled||shadowMode||!reviewed||!row||!result||!capacity||capacity.effective_units==null||busy||applying)return;setApplying(true);setActionError('');try{const minimumRateMinor=minimum?amount(minimum):Math.max(1,Math.round(row.amount_minor*.7)),maximumRateMinor=maximum?amount(maximum):Math.round(row.amount_minor*1.5),competitorRateMinor=competitor?amount(competitor):null,eventUpliftBasisPoints=Math.round(Number(event||0)*100),requestId=await onApply(prepareRevenueApproval(reviewed,{planId:row.plan.id,expectedVersion:row.plan.version,stayDate:row.stay_date,recommendedRateMinor:result.recommendedRateMinor}));if(requestId){const saved:RevenueDecisionReceipt={requestId,tenantId:tenant,propertyId:property,actorId:actor,propertyName:workspace.property.name,planId:row.plan.id,planName:row.plan.name,planVersion:row.plan.version,stayDate:row.stay_date,savedResponseAt:new Date().toISOString(),currentRateMinor:row.amount_minor,recommendedRateMinor:result.recommendedRateMinor,minimumRateMinor,maximumRateMinor,competitorRateMinor,eventUpliftBasisPoints,effectiveUnits:capacity.effective_units,reservedUnits:capacity.reserved_units,occupancyPercent:result.occupancyPercent,adjustmentBasisPoints:result.adjustmentBasisPoints,guardrail:result.guardrail,explanations:result.explanations};setReceipt(saved);try{setHistory(appendRevenueDecisionHistory(localStorage,scope,saved))}catch(reason){setActionError('The rate was saved, but '+(reason instanceof Error?reason.message:'its browser history could not be retained. Download the receipt now.'))}}setReviewedKey(null)}catch(reason){setActionError(reason instanceof Error?reason.message:'The recommended rate could not be saved. Refresh rates before retrying.')}finally{setApplying(false)}}
 if(!options.length)return <><RevenueApprovalRecoveryPanel actor={actor} tenant={tenant} property={property}/><section className="card"><h2>Revenue recommendation preview</h2><p>Add nightly prices before preparing decision support.</p></section></>;
 return <><RevenueApprovalRecoveryPanel actor={actor} tenant={tenant} property={property}/><section className="card pilot-settings"><div className="section-top" style={{padding:0}}><div><h2>Revenue recommendation</h2><p>Development preview · Human approval required · Never changes multiple nights automatically.</p></div><span className="pill amber">No automatic pricing</span></div><label className="field">Priced room night<select disabled={busy||applying} value={row?row.plan_id+'|'+row.stay_date:''} onChange={e=>{setSelected(e.target.value);setMinimum('');setMaximum('');edited()}}>{options.map(item=><option key={item.plan_id+'|'+item.stay_date} value={item.plan_id+'|'+item.stay_date}>{item.stay_date} · {item.plan.name} · {usd(item.amount_minor)}</option>)}</select></label><div className="form-grid"><label className="field">Minimum guardrail USD<input disabled={busy||applying} inputMode="decimal" value={minimum} placeholder={row?(row.amount_minor*.7/100).toFixed(2):''} onChange={e=>{setMinimum(e.target.value);edited()}}/></label><label className="field">Maximum guardrail USD<input disabled={busy||applying} inputMode="decimal" value={maximum} placeholder={row?(row.amount_minor*1.5/100).toFixed(2):''} onChange={e=>{setMaximum(e.target.value);edited()}}/></label><label className="field">Competitor median USD · optional<input disabled={busy||applying} inputMode="decimal" value={competitor} onChange={e=>{setCompetitor(e.target.value);edited()}}/></label><label className="field">Event uplift % · manager input<input disabled={busy||applying} type="number" min="0" max="50" step="0.01" value={event} onChange={e=>{setEvent(e.target.value);edited()}}/></label></div>{!capacity||capacity.effective_units==null?<p className="pilot-error">Effective capacity is unavailable for this room type and night. Configure inventory before preparing a recommendation.</p>:capacity.reserved_units>capacity.effective_units?<p className="pilot-error">This night is oversold. Resolve inventory before using decision support.</p>:null}{inputError&&<p className="pilot-error" role="alert">{inputError}</p>}{actionError&&<p className="pilot-error" role="alert">{actionError}</p>}{result&&<><div className="detail-grid"><div>Current rate<b>{usd(row!.amount_minor)}</b></div><div>Recommended rate<b>{usd(result.recommendedRateMinor)}</b></div><div>Combined adjustment<b>{result.adjustmentBasisPoints>=0?'+':''}{(result.adjustmentBasisPoints/100).toFixed(2)}%</b></div><div>Booked occupancy<b>{result.occupancyPercent.toFixed(1)}%</b></div><div>Guardrail applied<b>{result.guardrail}</b></div><div>Mode<b>Human approval</b></div></div><ul>{result.explanations.map(note=><li key={note}>{note}</li>)}</ul>{!shadowMode&&<><label className="pilot-check"><input type="checkbox" disabled={busy||applying} checked={reviewed} onChange={e=>{setReviewedKey(e.target.checked?reviewKey:null);setActionError('')}}/>I reviewed the selected night, current rate, capacity, competitor/event inputs, guardrails and every explanation.</label><button className="primary" disabled={!auditedSaveEnabled||!reviewed||busy||applying} onClick={()=>void apply()}>{applying?'Saving reviewed rate…':'Audited saving not yet available'}</button><p>Recommendation saving is blocked until the audited server release and recovery checks are qualified. Manual rate editing remains separate.</p></>}{shadowMode&&<p className="pilot-notice">Red Roof shadow mode: this preview cannot save a rate or send a rate to an OTA.</p>}</>}{receipt&&<div className="pilot-notice"><p>The PMS returned a successful save response. The decision was retained in this browser; download the receipt for the launch record.</p><button className="secondary" disabled={busy||applying} onClick={()=>{try{downloadReport('rate-decision-'+receipt.stayDate+'-'+receipt.planName,revenueDecisionReceiptRows(receipt));setActionError('')}catch{setActionError('The rate receipt could not be prepared.')}}}>Download reviewed rate receipt</button><p>Browser history is not the coordinated server audit and does not prove OTA delivery.</p></div>}{historyReady&&<section aria-label="Recent reviewed rate decisions"><div className="section-top"><div><h3>Recent decisions on this device</h3><p>Up to 100 successful responses for this staff account and property.</p></div><button className="secondary" disabled={busy||!history.length} onClick={()=>{try{downloadReport('rate-decision-history-'+workspace.property.name,revenueDecisionHistoryRows(history,workspace.property.name));setActionError('')}catch{setActionError('Rate-decision history could not be exported.')}}}>Export decision history</button></div>{history.length?<div className="pilot-table-wrap"><table className="pilot-table"><thead><tr><th>Saved</th><th>Night</th><th>Plan</th><th>Prior rate</th><th>Saved rate</th><th>Guardrail</th></tr></thead><tbody>{history.slice(0,10).map(item=><tr key={item.requestId}><td>{new Date(item.savedResponseAt).toLocaleString()}</td><td>{item.stayDate}</td><td>{item.planName}</td><td>{usd(item.currentRateMinor)}</td><td>{usd(item.recommendedRateMinor)}</td><td>{item.guardrail}</td></tr>)}</tbody></table></div>:<p className="pilot-empty">No reviewed recommendations have been saved from this browser yet.</p>}<p>This device history is supplemental. Coordinated server-side decision audit activation remains pending.</p></section>}</section></>;
}
